def dedupe_contacts(rows):
    """Deduplicate CRM contact rows according to CAS data rules.

    Returns a list of merged person dicts with the same keys as the input,
    in order of each person's earliest row in the input.
    """

    def norm_email(raw):
        e = (raw or "").strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.replace(".", "")
                local = local.split("+", 1)[0]
                e = local + "@gmail.com"
        return e

    def email_valid(e):
        if e.count("@") != 1:
            return False
        local, domain = e.split("@")
        return (
            local != ""
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def norm_phone(raw):
        digits = "".join(ch for ch in (raw or "") if ch.isdigit())
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    # Steps 1-4: normalize and drop rows with no valid contact method.
    kept = []  # (original_index, row, email_or_None, phone_or_None, last_key)
    for idx, row in enumerate(rows):
        e = norm_email(row.get("email", ""))
        e = e if email_valid(e) else None
        p = norm_phone(row.get("phone", ""))
        p = p if len(p) == 10 else None
        if e is None and p is None:
            continue
        last_key = (row.get("last_name", "") or "").strip().lower()
        kept.append((idx, row, e, p, last_key))

    # Step 5: union-find for transitive matching.
    parent = list(range(len(kept)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Keep the smaller index as root (not required, just tidy).
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}
    for k, (_, _, e, p, last_key) in enumerate(kept):
        keys = []
        if e is not None:
            keys.append(("email", e))
        if p is not None and last_key != "":
            keys.append(("phone_last", p, last_key))
        for key in keys:
            if key in first_seen:
                union(first_seen[key], k)
            else:
                first_seen[key] = k

    groups = {}
    for k in range(len(kept)):
        groups.setdefault(find(k), []).append(k)

    # Step 6: merge each group.
    def pick_latest(members, value_fn):
        """Value from the most recently updated member with a non-empty value.
        Ties on `updated` go to the earlier input row (members are in input order)."""
        best_val, best_upd = "", None
        for k in members:
            val = value_fn(k)
            if not val:
                continue
            upd = kept[k][1]["updated"]
            if best_upd is None or upd > best_upd:
                best_val, best_upd = val, upd
        return best_val

    people = []
    for members in groups.values():
        members.sort()  # input order (kept preserves input order)

        def field(name):
            return lambda k: (kept[k][1].get(name, "") or "").strip()

        tags = set()
        for k in members:
            for t in (kept[k][1].get("tags", "") or "").split(";"):
                t = t.strip().lower()
                if t:
                    tags.add(t)

        opted = any(
            (kept[k][1].get("opted_out", "") or "").strip().upper() == "Y"
            for k in members
        )

        person = {
            "first_name": pick_latest(members, field("first_name")),
            "last_name": pick_latest(members, field("last_name")),
            "email": pick_latest(members, lambda k: kept[k][2] or ""),
            "phone": pick_latest(members, lambda k: kept[k][3] or ""),
            "zip": pick_latest(members, field("zip")),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if opted else "N",
            "updated": max(kept[k][1]["updated"] for k in members),
        }
        people.append((kept[members[0]][0], person))

    # Step 7: order by earliest input row.
    people.sort(key=lambda pair: pair[0])
    return [p for _, p in people]
